/* Lot 14 : sols pixel fins dans toutes les pièces (demande Yann 27/11 « rajoute le sol pour tout ») */
(function () {
  const F = { tomettes: "data:image/png;base64,", damier: "data:image/png;base64,", labo: "data:image/png;base64,", pierre: "data:image/png;base64,", dalles: "data:image/png;base64,", parquet_clair: "data:image/png;base64," };
  const img = (u) => '<image href="' + u + '" x="0" y="0" width="200" height="200" preserveAspectRatio="none" style="image-rendering:pixelated;image-rendering:crisp-edges"/>';
  /* textures de sol des pièces -> sol fin */
  const TX = { sol_tomettes: "tomettes", sol_damier: "damier", sol_labo: "labo", sol_parquet: "pierre", sol_guilde: "dalles" };
  /* texFill est const : on remplace l'image des motifs #tx-sol_* (un carreau = tout le sol 200x200) */
  for (const k in TX) {
    const p = document.getElementById("tx-" + k), u = F[TX[k]];
    if (!p || !u) continue;
    p.setAttribute("width", 200); p.setAttribute("height", 200);
    const im = p.querySelector("image"); if (!im) continue;
    im.setAttribute("width", 200); im.setAttribute("height", 200);
    im.setAttribute("href", u); im.removeAttributeNS("http://www.w3.org/1999/xlink", "href");
    im.style.imageRendering = "pixelated";
  }
  /* floorArt : boutique (parquet) et sols de la maison */
  if (typeof floorArt === "function") {
    const _f = floorArt;
    floorArt = function (style) {
      const map = window.__inHouse ? { parquet: "parquet_clair", dalles: "dalles", tomettes: "tomettes", damier: "damier" } : { parquet: "parquet_clair" };
      const k = map[style];
      return k && F[k] ? img(F[k]) : _f.apply(this, arguments);
    };
  }
})();
